@tool
extends Node

func run() -> String:
	var d := DirAccess.open("res://")
	var paths := {
		"a2d": "addons/fightengine/assets/icons/at-icons/2d/box.svg.import",
		"b3d": "addons/fightengine/assets/icons/at-icons/3d/box.svg.import",
		"c2dw": "addons/fightengine/assets/icons/at-icons/2d/box_wireframe.svg.import",
		"d3dw": "addons/fightengine/assets/icons/at-icons/3d/box_wireframe.svg.import"
	}
	var uids := {}
	for k in paths.keys():
		var p := String(paths[k])
		if FileAccess.file_exists("res://" + p):
			var txt := FileAccess.get_file_as_string("res://" + p)
			var arr := txt.split("uid=\"")
			if arr.size() > 1:
				uids[k] = arr[1].get_slice("\"", 0)
			else:
				uids[k] = "NO_UID_FIELD"
		else:
			uids[k] = "FILE_MISSING"
	var deleted: Array = []
	if uids.get("b3d", "x") == uids.get("a2d", "y") and uids.get("b3d") != "FILE_MISSING":
		if d.remove(String(paths["b3d"])) == OK:
			deleted.append("3d/box.svg.import")
	if uids.get("d3dw", "x") == uids.get("c2dw", "y") and uids.get("d3dw") != "FILE_MISSING":
		if d.remove(String(paths["d3dw"])) == OK:
			deleted.append("3d/box_wireframe.svg.import")
	var rep := {"uids": uids, "deleted": deleted}
	var out := FileAccess.open("res://tools/gc_uid_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "UIDFIX deleted=" + str(deleted) + " a2d=" + str(uids.get("a2d")) + " b3d=" + str(uids.get("b3d"))
